update public.lessons l set enhancements = $ench${"davidTip":"When an action times out, do not reach for a longer timeout — run with `--debug` and read the actionability report Playwright prints. \"Element is not enabled\" and \"element intercepts pointer events\" tell you the real cause in plain words, and it is almost never \"Playwright is too fast\".","visualAid":{"type":"flow","title":"What happens before a single click","steps":[{"label":"Resolve the locator","detail":"Re-query the DOM for the element right now, not when the line was written."},{"label":"Run actionability checks","detail":"Attached, visible, stable, enabled, receives events — in order."},{"label":"Any check unmet?","detail":"Wait a beat and re-resolve, looping until the timeout."},{"label":"All checks met","detail":"Perform the click at the element's hit point."}]},"miniChallenge":"Take a test that has a `waitForTimeout` before a click. Delete the sleep, run the test ten times with `--repeat-each=10`, and confirm auto-waiting made the wait redundant."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 6 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A team had a suite that failed a couple of times a week, always on a different test, always green on rerun. They lived with it for months by rerunning the pipeline. When someone finally logged the failures, a pattern emerged in a day: every flaky test authenticated as the same shared seed user, and they collided whenever two ran in parallel. Giving each test its own user removed the entire class of failures at once — the \"random\" flakiness had been one design fault all along.","visualAid":{"type":"comparison","title":"Five causes of flakiness and their fixes","headers":["Cause","Typical symptom","Structural fix"],"rows":[["Timing","Fails under load, passes on rerun","Auto-waiting and web-first assertions"],["Shared state","A different test fails each time","Isolated per-test data"],["Poor test data","Breaks when data changes","Create and own the data you need"],["Environment","Fails only in CI","Pin viewport, locale, browser versions"],["Test ordering","Only passes in one order","Make every test self-sufficient"]]},"davidTip":"When you hit a flake, resist the rerun button for five minutes and ask \"which category is this?\" first. The rerun tells you nothing; the category tells you the fix. A team that names causes gets a stable suite, a team that reruns gets a slow one that still lies to them."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 6 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"badGood":{"label":"waiting for an async result","bad":"~~~ts\nawait page.getByRole('button', { name: 'Save' }).click();\n// Hope 3s is enough for the save to complete and the toast to appear.\nawait page.waitForTimeout(3000);\nawait expect(page.getByRole('alert')).toHaveText('Saved');\n~~~","good":"~~~ts\nawait page.getByRole('button', { name: 'Save' }).click();\n// The assertion IS the wait: it retries until the toast says \"Saved\".\nawait expect(page.getByRole('alert')).toHaveText('Saved');\n~~~"},"davidTip":"The tell-tale sign of a hard wait is that nobody can explain the number. Ask \"why three seconds and not two, or five?\" — there is never an answer, because the number was tuned until the test stopped failing that afternoon. A web-first assertion needs no such number, which is exactly why it does not rot.","miniChallenge":"Write a test against an eventually-consistent endpoint (a job you trigger, then poll) using `expect(...).toPass()`. Confirm it passes when the job is fast and still passes when you artificially slow the job down."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 6 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team's suite relied on selectors auto-generated from a component library's class names. A routine library upgrade changed those hashed class names and several hundred tests failed overnight — not one because of a real defect. The rescue was not to pin the old library but to rewrite the worst offenders as `getByRole` and `getByLabel`; the rebuilt tests then sailed through the next two upgrades untouched, because they were coupled to what users see rather than to a build artefact.","badGood":{"label":"brittle vs resilient locator","bad":"~~~ts\nawait page.locator('div.MuiCard-root > div:nth-child(2) > button.css-1a2b3c').click();\n~~~","good":"~~~ts\nawait page\n  .getByRole('listitem')\n  .filter({ hasText: 'Mechanical keyboard' })\n  .getByRole('button', { name: 'Add to basket' })\n  .click();\n~~~"},"miniChallenge":"Find one locator in your suite built on a class-name hash or an `nth-child` path. Rewrite it by role and accessible name, then have a colleague restructure that component and confirm the test still passes."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 6 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"badGood":{"label":"waiting for a network result","bad":"~~~ts\nawait page.getByRole('button', { name: 'Place order' }).click();\nawait page.waitForLoadState('networkidle'); // never settles: the page polls for notifications\nawait expect(page.getByRole('heading', { name: 'Order confirmed' })).toBeVisible();\n~~~","good":"~~~ts\nconst orderPosted = page.waitForResponse(r => r.url().includes('/api/orders') && r.ok());\nawait page.getByRole('button', { name: 'Place order' }).click();\nawait orderPosted;\nawait expect(page.getByRole('heading', { name: 'Order confirmed' })).toBeVisible();\n~~~"},"davidTip":"When a page \"never finishes loading\" in your test, open the network tab in a trace — you will usually find a heartbeat or analytics request firing every few seconds. That is why `networkidle` is a trap. Wait for the one response your feature actually produces and ignore the noise.","visualAid":{"type":"comparison","title":"Async patterns and the signal to wait for","headers":["Pattern","Wrong: fixed wait","Right: real signal"],"rows":[["Native dialog","Sleep then click","page.on('dialog') before the action"],["Toast message","Sleep to catch it","Retrying assertion on the alert"],["Animation","Sleep out the transition","Stability check, or wait on a state class"],["Navigation","Sleep after click","toHaveURL or waitForURL"],["Network call","networkidle or sleep","waitForResponse on the specific endpoint"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 6 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team had one test that failed roughly once a fortnight and had been reran-into-green so many times nobody trusted it. An engineer finally ran it fifty times with `--repeat-each`, caught two failures, and opened the traces. Both showed the same thing: a pricing call still in flight when the assertion checked the total. A three-line `waitForResponse` fixed it permanently. The wider change was cultural — the team stopped closing flaky tickets on a rerun and started requiring a reproduced trace, and their fortnightly mystery failures dried up over a quarter.","badGood":{"label":"fixing a flaky assertion","bad":"~~~ts\n// Reran until it \"mostly\" passed, then padded the timeout to hide the race.\nawait page.getByRole('button', { name: 'Recalculate' }).click();\nawait expect(page.getByTestId('order-total')).toHaveText('£42.00', { timeout: 30000 });\n~~~","good":"~~~ts\n// Wait for the actual pricing response, so the assertion checks fresh data.\nconst priced = page.waitForResponse(r => r.url().includes('/api/price') && r.ok());\nawait page.getByRole('button', { name: 'Recalculate' }).click();\nawait priced;\nawait expect(page.getByTestId('order-total')).toHaveText('£42.00');\n~~~"},"visualAid":{"type":"flow","title":"The flaky-test rescue loop","steps":[{"label":"Reproduce","detail":"Run with --repeat-each until the failure is reliable to trigger."},{"label":"Capture","detail":"Record a trace of a failing run (--trace on or on-first-retry)."},{"label":"Diagnose","detail":"Scrub the trace to the failing step; read the DOM, network and log."},{"label":"Fix the cause","detail":"Address the category — race, overlay, shared data — not the timeout."},{"label":"Prove it","detail":"Re-run many times; many greens, not one, is the evidence."}]},"miniChallenge":"Introduce a deliberate race into a passing test, reproduce it with `--repeat-each=30`, then fix it with a targeted wait and show it survives another 50 runs. Keep the trace of the original failure as evidence."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 6 and l.lesson_number = 6;

